        try{
            $this->db->prepare("UPDATE mobile_intake_reports SET status='pending_review',lease_token_hash=NULL,lease_until=NULL,updated_at=? WHERE status='leased' AND lease_until<?")->execute([$now,$now]);
            $sql="SELECT r.report_uuid,r.estate_id,r.actor_username,r.actor_role,r.entry_kind,r.payload_json,r.revision FROM mobile_intake_reports r JOIN app_users u ON u.user_id=r.actor_id JOIN mobile_sessions s ON s.token_hash=r.origin_token_hash JOIN mobile_session_capabilities c ON c.token_hash=s.token_hash AND c.capability='intake.submit' WHERE r.status='pending_review' AND u.enabled=1 AND u.role=r.actor_role AND u.role IN ('operator','admin') AND s.revoked_at IS NULL AND s.expires_at>=? AND (SELECT COUNT(*) FROM mobile_intake_attachments a WHERE a.report_uuid=r.report_uuid AND a.deleted_at IS NULL AND a.upload_state='complete')=r.attachment_count ORDER BY r.received_at LIMIT ".$limit.($driver==='mysql'?' FOR UPDATE':'');$q=$this->db->prepare($sql);$q->execute([$now]);$reports=$q->fetchAll(PDO::FETCH_ASSOC);$claim=$this->db->prepare("UPDATE mobile_intake_reports SET status='leased',lease_token_hash=?,lease_until=?,delivery_attempts=delivery_attempts+1,revision=revision+1,updated_at=? WHERE report_uuid=? AND status='pending_review'");$rows=[];
            foreach($reports as $row){$a=$this->db->prepare("SELECT attachment_uuid,file_sha256,media_type,byte_count FROM mobile_intake_attachments WHERE report_uuid=? AND deleted_at IS NULL AND upload_state='complete' ORDER BY uploaded_at");$a->execute([(string)$row['report_uuid']]);$token=$this->randomToken();$claim->execute([hash('sha256',$token),$leaseUntil,$now,(string)$row['report_uuid']]);if($claim->rowCount()!==1)continue;$rows[]=['report_uuid'=>(string)$row['report_uuid'],'estate_id'=>(string)$row['estate_id'],'actor'=>['username'=>(string)$row['actor_username'],'server_role'=>(string)$row['actor_role']],'authority'=>['capability'=>'intake.submit','session_active'=>true,'checked_at'=>gmdate('Y-m-d\TH:i:s\Z',strtotime($now))],'kind'=>(string)$row['entry_kind'],'payload'=>json_decode((string)$row['payload_json'],true,64,JSON_THROW_ON_ERROR),'revision'=>(string)((int)$row['revision']+1),'lease_token'=>$token,'lease_until'=>$leaseUntil,'attachments'=>$a->fetchAll(PDO::FETCH_ASSOC)];}
