    }

    /** @return array<string,mixed> */
    public function health():array
    {
        $retention=DatabaseTime::from(DatabaseTime::now(),-2592000);$q=$this->db->prepare("SELECT COUNT(*) retained_files,COALESCE(SUM(byte_count),0) retained_bytes,MIN(uploaded_at) oldest_retained,SUM(CASE WHEN delete_requested_at IS NOT NULL THEN 1 ELSE 0 END) pending_cleanup,MIN(CASE WHEN delete_requested_at IS NOT NULL THEN delete_requested_at ELSE NULL END) oldest_cleanup,COALESCE(SUM(CASE WHEN delete_requested_at IS NOT NULL THEN byte_count ELSE 0 END),0) pending_bytes,SUM(CASE WHEN delete_requested_at IS NULL AND uploaded_at<? THEN 1 ELSE 0 END) expired_unrequested FROM mobile_intake_attachments WHERE deleted_at IS NULL");$q->execute([$retention]);$row=$q->fetch(PDO::FETCH_ASSOC);$referenced=[];$missing=0;$outside=0;$root=$this->privateDir.'/';$files=$this->db->query('SELECT stored_path FROM mobile_intake_attachments WHERE deleted_at IS NULL')->fetchAll(PDO::FETCH_COLUMN);
